CREATE TABLE customers (
  id     int PRIMARY KEY,
  name   text NOT NULL,
  region text
);
CREATE TABLE orders (
  id          int PRIMARY KEY,
  customer_id int,            -- NULL for guest checkouts
  status      text,           -- 'paid', 'pending', 'refunded', ...
  total       numeric(10,2) NOT NULL,
  placed_on   date NOT NULL
);

